#!/usr/bin/env node
'use strict';

/**
 * anti-rubber-stamp.js — Detects rubber-stamp approvals via timing analysis.
 *
 * Catches approvals that happen too fast to represent genuine review.
 * Tracks per-architecture approval patterns over time.
 *
 * Usage:
 *   node .fastops/anti-rubber-stamp.js --mission MISSION_ID          — Full report
 *   node .fastops/anti-rubber-stamp.js --mission MISSION_ID --check  — Quick suspicious flag
 *   node .fastops/anti-rubber-stamp.js --patterns                    — Cross-mission pattern report
 *
 * Exports:
 *   checkApprovalTiming(missionId, approverName, approvalTimestamp)
 *   getApprovalVelocityReport(missionId)
 */

