#!/usr/bin/env node
'use strict';

/**
 * anti-rubber-stamp.js — Detects rubber-stamp approvals via timing analysis.
 *
 * Catches approvals that happen too fast to represent genuine review.
 * Tracks per-architecture approval patterns over time.
 *
 * Usage:
 *   node .fastops/anti-rubber-stamp.js --mission MISSION_ID          — Full report
 *   node .fastops/anti-rubber-stamp.js --mission MISSION_ID --check  — Quick suspicious flag
 *   node .fastops/anti-rubber-stamp.js --patterns                    — Cross-mission pattern report
 *
 * Exports:
 *   checkApprovalTiming(missionId, approverName, approvalTimestamp)
 *   getApprovalVelocityReport(missionId)
 */

const fs = require('fs');
const path = require('path');

const FASTOPS_DIR = __dirname;
const SIGNOFF_DIR = path.join(FASTOPS_DIR, 'sign-offs');
const METRICS_FILE = path.join(FASTOPS_DIR, '.approval-metrics.jsonl');
const MISSIONS_DIR = path.join(FASTOPS_DIR, '..', 'missions');

// --- Thresholds ---
const LINES_PER_MINUTE = 500;           // Estimated readable lines per minute
const SUSPICIOUS_FAST_MINUTES = 2;      // Approval under 2 min is suspicious
const RUBBER_STAMP_RATE_THRESHOLD = 0.9; // >90% approval rate flags the architecture
const MIN_APPROVALS_FOR_PATTERN = 3;    // Need at least 3 approvals before flagging rate

// --- Helpers ---

function getArchFamily(model) {
  if (!model) return 'unknown';
  const m = model.toLowerCase();
  if (m.includes('claude') || m.includes('haiku') || m.includes('opus') || m.includes('sonnet')) return 'anthropic';
  if (m.includes('gemini') || m.includes('google')) return 'google';
  if (m.includes('gpt') || m.includes('openai') || m.includes('o1') || m.includes('o3')) return 'openai';
  if (m.includes('grok') || m.includes('xai')) return 'xai';
  if (m.includes('kimi') || m.includes('moonshot')) return 'moonshot';
  if (m.includes('deepseek')) return 'deepseek';
  if (m.includes('mistral')) return 'mistral';
  if (m.includes('qwen')) return 'qwen';
  if (m.includes('llama') || m.includes('meta')) return 'meta';
  return model;
}

function readSignoffs(missionId) {
  const f = path.join(SIGNOFF_DIR, `${missionId}.jsonl`);
  if (!fs.existsSync(f)) return [];
  return fs.readFileSync(f, 'utf8').trim().split('\n')
    .map(l => { try { return JSON.parse(l); } catch { return null; } })
    .filter(Boolean);
}

/**
 * Estimate artifact size for a mission by counting lines in the mission directory.
 * Falls back to a default if directory doesn't exist or is empty.
 */
function estimateArtifactLines(missionId) {
  // Try to find the mission directory by matching against known folder names
  const candidates = [
    path.join(MISSIONS_DIR, missionId),
    path.join(MISSIONS_DIR, missionId.toLowerCase()),
  ];

  // Also try matching by prefix (e.g., STRESS-TEST-V105 -> stress-test)
  if (fs.existsSync(MISSIONS_DIR)) {
    try {
      const dirs = fs.readdirSync(MISSIONS_DIR);
      for (const d of dirs) {
        if (missionId.toLowerCase().startsWith(d.toLowerCase())) {
          candidates.push(path.join(MISSIONS_DIR, d));
        }
      }
    } catch {}
  }

  let totalLines = 0;
  for (const dir of candidates) {
    if (!fs.existsSync(dir) || !fs.statSync(dir).isDirectory()) continue;
    totalLines += countLinesInDir(dir);
  }

  // Default to 250 lines if we can't find the artifact (assumes ~30 sec read minimum)
  return totalLines > 0 ? totalLines : 250;
}

function countLinesInDir(dir) {
  let total = 0;
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        total += countLinesInDir(full);
      } else if (entry.isFile() && /\.(js|ts|md|json|jsonl|txt|py|sh|yaml|yml)$/i.test(entry.name)) {
        try {
          const content = fs.readFileSync(full, 'utf8');
          total += content.split('\n').length;
        } catch {}
      }
    }
  } catch {}
  return total;
}

/**
 * Find the earliest timestamp in the sign-off record — this is the baseline
 * (artifact was posted / review was requested around this time).
 * We use the first non-APPROVE entry or the earliest entry overall as the
 * "artifact posted" marker.
 */
function getArtifactPostedTime(signoffs) {
  if (signoffs.length === 0) return null;
  // The earliest sign-off timestamp serves as the baseline.
  // In practice, the first entry is typically either a submission marker or
  // the first reviewer's action.
  let earliest = null;
  for (const s of signoffs) {
    const t = new Date(s.ts).getTime();
    if (earliest === null || t < earliest) earliest = t;
  }
  return earliest;
}

// --- Core exports ---

/**
 * Check whether a specific approval looks like a rubber stamp.
 *
 * @param {string} missionId
 * @param {string} approverName - agent name to check
 * @param {string} approvalTimestamp - ISO timestamp of the approval
 * @returns {{ suspicious: boolean, reason: string, timeToApproval: number, estimatedReadTime: number }}
 */
function checkApprovalTiming(missionId, approverName, approvalTimestamp) {
  const signoffs = readSignoffs(missionId);
  if (signoffs.length === 0) {
    return {
      suspicious: false,
      reason: 'No sign-off record found for this mission.',
      timeToApproval: 0,
      estimatedReadTime: 0,
    };
  }

  const artifactPosted = getArtifactPostedTime(signoffs);
  if (artifactPosted === null) {
    return {
      suspicious: false,
      reason: 'Could not determine artifact posted time.',
      timeToApproval: 0,
      estimatedReadTime: 0,
    };
  }

  const approvalTime = new Date(approvalTimestamp).getTime();
  const timeToApprovalMs = approvalTime - artifactPosted;
  const timeToApprovalMin = timeToApprovalMs / 60000;

  const artifactLines = estimateArtifactLines(missionId);
  const estimatedReadTime = Math.max(1, artifactLines / LINES_PER_MINUTE); // minutes

  const reasons = [];
  let suspicious = false;

  // Check 1: Faster than estimated read time
  if (timeToApprovalMin > 0 && timeToApprovalMin < estimatedReadTime * 0.5) {
    suspicious = true;
    reasons.push(
      `Approved in ${timeToApprovalMin.toFixed(1)}min but artifact is ~${artifactLines} lines ` +
      `(estimated ${estimatedReadTime.toFixed(1)}min read time). Less than half the read time.`
    );
  }

  // Check 2: Under absolute minimum threshold
  if (timeToApprovalMin > 0 && timeToApprovalMin < SUSPICIOUS_FAST_MINUTES) {
    suspicious = true;
    reasons.push(
      `Approved in ${timeToApprovalMin.toFixed(1)}min — under the ${SUSPICIOUS_FAST_MINUTES}min minimum threshold.`
    );
  }

  // Check 3: First action in the record (i.e., they are the earliest — possible self-approve)
  if (timeToApprovalMs === 0) {
    // This approver is the first entry — could be the artifact poster approving their own work
    const approverEntry = signoffs.find(
      s => s.agent === approverName && s.verdict === 'APPROVE'
    );
    if (approverEntry && new Date(approverEntry.ts).getTime() === artifactPosted) {
      reasons.push('This approver is the first entry in the sign-off record — possible self-approval.');
      // Not necessarily suspicious on its own, so don't set flag just for this
    }
  }

  // Record metric
  const approverEntry = signoffs.find(
    s => s.agent === approverName && s.verdict === 'APPROVE' && s.ts === approvalTimestamp
  );
  const architecture = approverEntry ? (approverEntry.architecture || getArchFamily(approverEntry.model)) : 'unknown';
  recordMetric({
    missionId,
    approver: approverName,
    architecture,
    timeToApprovalMin: Math.round(timeToApprovalMin * 100) / 100,
    estimatedReadTimeMin: Math.round(estimatedReadTime * 100) / 100,
    suspicious,
    ts: new Date().toISOString(),
  });


