  if (FORCE_MODEL) return FORCE_MODEL;
  // Rotate based on day of year
  const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
  return AUDIT_MODELS[dayOfYear % AUDIT_MODELS.length];
}

// ─── State Gathering ────────────────────────────────────────────────────────

function tryRead(filePath) {
  try { return fs.readFileSync(filePath, 'utf8'); } catch { return ''; }
}

function tryReadJSON(filePath) {
  try { return JSON.parse(fs.readFileSync(filePath, 'utf8')); } catch { return null; }
}

function getLastSessionHandoff() {
  const handoff = tryRead(path.join(FASTOPS, 'HANDOFF.md'));
  // Get master summary (first ~3000 chars)
  return handoff.substring(0, 3000);
}

function getRecentDebriefs() {
  const today = new Date().toISOString().slice(0, 10);
  const yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);

  let debriefs = [];
  for (const date of [today, yesterday]) {
    const filePath = path.join(FASTOPS, 'subagent-debriefs', `${date}.jsonl`);
    try {
      const lines = fs.readFileSync(filePath, 'utf8').trim().split('\n');
      debriefs = debriefs.concat(
        lines.slice(-15).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean)
      );
    } catch {}
  }
  return debriefs;
}

function getRecentCommits(hours = 24) {
  try {
    const since = new Date(Date.now() - hours * 3600000).toISOString();
    return execSync(
      `git log --oneline --since="${since}" --no-merges`,
      { cwd: ROOT, encoding: 'utf8', timeout: 5000 }
    ).trim().split('\n').filter(Boolean).slice(0, 30);
  } catch { return []; }
}

function getUncommittedWork() {
  try {
    const status = execSync('git status --short', { cwd: ROOT, encoding: 'utf8', timeout: 5000 });
    const lines = status.trim().split('\n').filter(Boolean);
    const modified = lines.filter(l => l.startsWith(' M') || l.startsWith('M '));
    const untracked = lines.filter(l => l.startsWith('??'));
    return { modified: modified.length, untracked: untracked.length, files: lines.slice(0, 20) };
  } catch { return { modified: 0, untracked: 0, files: [] }; }
}

function getToolMaturity() {
  // Scan .fastops/*.js for tools, check if they're wired anywhere
  const tools = [];
  try {
    const jsFiles = fs.readdirSync(FASTOPS).filter(f => f.endsWith('.js') && !f.startsWith('.'));

    // What's wired into hooks?
    const settingsPath = path.join(ROOT, '.claude', 'settings.json');
    const settings = tryRead(settingsPath);

    // What's referenced in session-start?
    const sessionStart = tryRead(path.join(ROOT, '.claude', 'commands', 'session-start.md'));

    // What's referenced in preflight?
    const preflight = tryRead(path.join(FASTOPS, 'preflight.js'));

    // What's referenced in HANDOFF?
    const handoff = tryRead(path.join(FASTOPS, 'HANDOFF.md'));

    for (const f of jsFiles) {
      const name = f.replace('.js', '');
      const inHooks = settings.includes(name);
      const inSessionStart = sessionStart.includes(name);
      const inPreflight = preflight.includes(name);
      const inHandoff = handoff.includes(name);

      // Check if any other tool requires/references it
      let referencedBy = 0;
      for (const other of jsFiles) {
        if (other === f) continue;
        const content = tryRead(path.join(FASTOPS, other));
        if (content.includes(name)) referencedBy++;
      }

      // Check git log for usage by other agents
      let usedInCommits = 0;
      try {
        const log = execSync(
          `git log --oneline --all --grep="${name}" -- . | head -5`,
          { cwd: ROOT, encoding: 'utf8', timeout: 3000 }
        ).trim();
        usedInCommits = log ? log.split('\n').length : 0;
      } catch {}

      let maturity = 'BUILT';
      if (inHooks || inSessionStart || inPreflight) maturity = 'WIRED';
      if (referencedBy > 0 || usedInCommits > 2) maturity = 'USED';
      if (maturity === 'USED' && (inHooks || inPreflight)) maturity = 'ADOPTED';

      tools.push({
        name,
        maturity,
        wired_in: [
          inHooks ? 'hooks' : null,
          inSessionStart ? 'session-start' : null,
          inPreflight ? 'preflight' : null,
          inHandoff ? 'handoff' : null
        ].filter(Boolean),
        referenced_by: referencedBy,
        commit_mentions: usedInCommits
      });
    }
  } catch {}

  const counts = { BUILT: 0, WIRED: 0, USED: 0, ADOPTED: 0 };
  tools.forEach(t => { counts[t.maturity] = (counts[t.maturity] || 0) + 1; });

  return {
    tools: tools.sort((a, b) => {
      const order = { BUILT: 0, WIRED: 1, USED: 2, ADOPTED: 3 };
      return order[a.maturity] - order[b.maturity];
    }),
    counts,
    orphans: tools.filter(t => t.maturity === 'BUILT').map(t => t.name)
  };
}

function getRecentVoice() {
  try {
    const voicePath = path.join(FASTOPS, '.voice-log.jsonl');
    const lines = fs.readFileSync(voicePath, 'utf8').trim().split('\n');
    return lines.slice(-5).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  } catch { return []; }
}

